import{_ as i,o as a,c as e,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ordered Bucket Index Shards in RGW - Eric Ivancich, IBM","description":"","frontmatter":{"title":"Ordered Bucket Index Shards in RGW - Eric Ivancich, IBM","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["Ceph","RGW","Distributed Storage","Ordered Sharding","Bucket Indexing"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ordered_Bucket_Index_Shards_in_RGW_-_Eric_Ivancich_IBM.md","filePath":"posts/2025/Ordered_Bucket_Index_Shards_in_RGW_-_Eric_Ivancich_IBM.md","lastUpdated":1780459816000}'),t={name:"posts/2025/Ordered_Bucket_Index_Shards_in_RGW_-_Eric_Ivancich_IBM.md"};function o(n,l,s,u,d,c){return a(),e("div",null,[...l[0]||(l[0]=[r('<p>在这次Ceph会议中，IBM的Eric Ivancich详细介绍了RGW（Rados Gateway）中的有序桶索引分片（Ordered Bucket Index Shards）的相关内容。以下是会议的要点总结：</p><h3 id="会议基本信息" tabindex="-1">会议基本信息 <a class="header-anchor" href="#会议基本信息" aria-label="Permalink to &quot;会议基本信息&quot;">​</a></h3><ul><li><strong>演讲人</strong>：Eric Ivancich (IBM)</li><li><strong>背景</strong>：Eric在Ceph领域有超过十年的工作经验，曾就职于Cohort FS（后被Red Hat收购），现属于IBM存储团队。</li></ul><h3 id="核心讨论内容" tabindex="-1">核心讨论内容 <a class="header-anchor" href="#核心讨论内容" aria-label="Permalink to &quot;核心讨论内容&quot;">​</a></h3><h4 id="_1-rgw桶索引基础" tabindex="-1">1. RGW桶索引基础 <a class="header-anchor" href="#_1-rgw桶索引基础" aria-label="Permalink to &quot;1. RGW桶索引基础&quot;">​</a></h4><ul><li><strong>当前架构</strong>： <ul><li>RGW维护包含桶元数据的系列对象，包括桶入口点、桶实例对象和分片。</li></ul></li><li><strong>Resharding机制</strong>： <ul><li>每个分片最多容纳约100,000个对象。</li><li>动态重分片阈值触发扩容/缩容。</li></ul></li></ul><h4 id="_2-哈希分片索引现状" tabindex="-1">2. 哈希分片索引现状 <a class="header-anchor" href="#_2-哈希分片索引现状" aria-label="Permalink to &quot;2. 哈希分片索引现状&quot;">​</a></h4><ul><li><strong>工作原理</strong>： <ul><li>对对象名进行哈希计算，取模确定目标分片。</li></ul></li><li><strong>优点</strong>： <ul><li>恒定时间计算分片位置。</li><li>对象分布相对均匀。</li></ul></li><li><strong>缺点</strong>： <ul><li>重分片是全局操作。</li><li>桶列表操作复杂且I/O密集。</li></ul></li></ul><h4 id="_3-有序分片索引提案" tabindex="-1">3. 有序分片索引提案 <a class="header-anchor" href="#_3-有序分片索引提案" aria-label="Permalink to &quot;3. 有序分片索引提案&quot;">​</a></h4><ul><li><strong>核心改进</strong>： <ul><li>维护分片间的词典序。</li><li>使用OMAP记录分片切割点。</li></ul></li><li><strong>优势</strong>： <ul><li>桶列表I/O大幅降低。</li><li>支持局部重分片。</li></ul></li><li><strong>挑战</strong>： <ul><li>热点问题。</li><li>分片定位复杂度增加。</li><li>版本桶的特殊约束。</li></ul></li></ul><h4 id="_4-技术实现细节" tabindex="-1">4. 技术实现细节 <a class="header-anchor" href="#_4-技术实现细节" aria-label="Permalink to &quot;4. 技术实现细节&quot;">​</a></h4><ul><li><strong>分片命名方案</strong>： <ul><li>改用分层命名。</li><li>通过模拟测试验证。</li></ul></li><li><strong>性能考量</strong>： <ul><li>通过缓存减少bucket instance object的频繁读取。</li><li>对RocksDB的OMAP操作影响需进一步评估。</li></ul></li></ul><h4 id="_5-路线图" tabindex="-1">5. 路线图 <a class="header-anchor" href="#_5-路线图" aria-label="Permalink to &quot;5. 路线图&quot;">​</a></h4><ul><li><strong>目标版本</strong>： <ul><li>Ceph Octopus的次版本发布。</li><li>下游RHCS 9.1版本集成。</li></ul></li></ul><h3 id="q-a重点摘要" tabindex="-1">Q&amp;A重点摘要 <a class="header-anchor" href="#q-a重点摘要" aria-label="Permalink to &quot;Q&amp;A重点摘要&quot;">​</a></h3><ul><li><strong>分片数量限制</strong>： <ul><li>OMAP限制100,000键值对。</li><li>超大规模解决方案可能采用混合索引。</li></ul></li><li><strong>迁移策略</strong>： <ul><li>通过<code>radosgw-admin</code>命令将现有哈希分片转换为有序分片。</li><li>支持配置新建桶的默认分片策略。</li></ul></li><li><strong>性能影响</strong>： <ul><li>CPU开销：插入/删除操作可能涉及对数时间复杂度的排序。</li><li>RocksDB压缩：需关注频繁插入是否导致额外压缩开销。</li></ul></li><li><strong>切割点确定</strong>： <ul><li>动态确定。</li><li>当前需全扫描分片，未来可能开发专用CLS操作。</li></ul></li></ul><h3 id="行动计划" tabindex="-1">行动计划 <a class="header-anchor" href="#行动计划" aria-label="Permalink to &quot;行动计划&quot;">​</a></h3><ul><li><strong>短期</strong>： <ul><li>完成Octopus版本的有序分片索引实现。</li><li>完善版本桶的特殊情况处理。</li></ul></li><li><strong>长期</strong>： <ul><li>评估混合索引方案的可行性。</li><li>优化超大规模桶的支持能力。</li></ul></li></ul><h3 id="关键术语" tabindex="-1">关键术语 <a class="header-anchor" href="#关键术语" aria-label="Permalink to &quot;关键术语&quot;">​</a></h3><ul><li>Ceph/RGW/CRUSH algorithm</li><li>object storage/block storage/file system storage</li><li>OSD/MON/MDS/PG</li><li>RADOS/librados/libcephfs</li><li>cephfs/rbd/radosgw (RGW)</li><li>RESTful API/authentication/authorization</li><li>erasure coding/replication/snapshots/clones</li><li>thin provisioning/iSCSI/Fibre Channel</li><li>NFS/CIFS/POSIX</li><li>Kubernetes/Docker/containerization</li><li>AWS/Azure/Google Cloud/hybrid cloud/multi-cloud</li><li>SSD/HDD/JBOD/SAN/NAS</li><li>failure domain/recovery/resilience</li><li>caching/compression/deduplication/tiering</li></ul>',20)])])}const g=i(t,[["render",o]]);export{_ as __pageData,g as default};
